// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 fuzzedInterfaceId) public {
        // General rule: for every interfaceId, c.supportsInterface(id) must return true
        // whenever id is IERC165's interfaceId or IAccessControl's interfaceId.
        // The mutant drops the IERC165 fallback, so it returns false for IERC165.
        bool okIerc165 = c.supportsInterface(type(IERC165).interfaceId);
        assertTrue(
            okIerc165 == true || !(fuzzedInterfaceId == type(IERC165).interfaceId),
            "IERC165 support must be advertised"
        );
    }
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 selector, uint256 rawId) public {
        // WIDE domain: the fuzzer picks which interface to probe (contract-defined ids)
        // or an arbitrary id, keeping the IERC165 probe reachable with high probability.
        selector = bound(selector, 0, 2);
        bytes4 iid;
        if (selector == 0) {
            iid = type(IERC165).interfaceId;
        } else if (selector == 1) {
            iid = type(IAccessControl).interfaceId;
        } else {
            iid = bytes4(uint32(rawId));
        }

        // General rule: interface support is exactly {IERC165, IAccessControl} —
        // inheritance through ERC165 guarantees IERC165 is reported as supported.
        bool expected = (iid == type(IERC165).interfaceId) || (iid == type(IAccessControl).interfaceId);
        bool ok = true;
        try c.supportsInterface(iid) returns (bool supported) {
            ok = (supported == expected);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 iid, address actor) public {
        // 1. keep the whole bytes4 domain admissible (no narrowing)
        // 2. drive c through its public supportsInterface from an arbitrary actor
        vm.prank(actor);
        bool got = c.supportsInterface(iid);
        // 3. general rule: C advertises exactly IAccessControl's and IERC165's interface ids
        assertTrue(
            got == (iid == type(IAccessControlId).interfaceId || iid == type(IERC165Id).interfaceId),
            "supportsInterface must reflect both IAccessControl and its ERC165 super fallback"
        );
    }
}

// minimal local stand-ins for the interfaces inherited by C (not re-declaring C itself)
interface IAccessControlId {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
}

interface IERC165Id {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

