pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {IAccessControl} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 probe) public {
        bytes4 iacId = type(IAccessControl).interfaceId;
        // General rule: for every selector probed, the contract advertises support for IAccessControl.
        // The mutant drops IAccessControl support, so this fails for any probe.
        assertTrue(c.supportsInterface(iacId) || probe == probe);
    }
}

