pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address actor) public {
        // The deployer (this contract) holds TIMELOCK_ADMIN_ROLE, which administers
        // every role, so it can grant an arbitrary role to an arbitrary account.
        vm.prank(address(this));
        c.grantRole(role, actor);
        // General rule: after granting, the account must report membership in the role.
        assertTrue(c.hasRole(role, actor));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address actor, bytes32 salt, uint256 delay) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        delay = bound(delay, 0, 365 days);

        bytes32 proposerRole = c.PROPOSER_ROLE();

        // The deployer (this test contract) holds TIMELOCK_ADMIN_ROLE, the admin
        // of PROPOSER_ROLE, so granting must succeed for any admissible actor.
        bool granted = true;
        try c.grantRole(proposerRole, actor) {
            granted = true;
        } catch {
            granted = false;
        }

        // General rule: any account granted PROPOSER_ROLE can schedule an
        // operation (with a delay >= the minimum delay) without reverting.
        bool scheduled = true;
        if (granted) {
            vm.prank(actor);
            try c.schedule(address(this), 0, "", bytes32(0), salt, delay) {
                scheduled = true;
            } catch {
                scheduled = false;
            }
        } else {
            scheduled = false;
        }

        assertTrue(scheduled);
    }
}
